function e(e){return String(e).normalize(`NFD`).replace(/[\u0300-\u036f]/g,``).toLocaleLowerCase().trim()}function t(n,r){if(n!=null){if(Array.isArray(n)){n.forEach(e=>t(e,r));return}if(typeof n==`object`){Object.values(n).forEach(e=>t(e,r));return}r.push(e(n))}}function n(n,...r){let i=e(n).split(/\s+/).filter(Boolean);if(!i.length)return!0;let a=[];return r.forEach(e=>t(e,a)),i.every(e=>a.some(t=>t.includes(e)))}export{n as t};